mapper.select:
select o.id as id, o.order_no as orderNo, o.title as title, o.channel as channel, o.customer as customer, o.customer_account as customerAccount, o.contact as contact, o.amount as amount, o.owner_id as ownerId, o.status as status, o.priority as priority, o.deadline as deadline, o.requirement as requirement, o.unread as unread, o.paid as paid, o.received_amount as receivedAmount, o.assign_state as assignState, (select count(*) from jiedan_approval ap where ap.order_id = o.id and ap.status = 'pending') as pendingApprovals, o.revisions as revisions, o.version as version, o.create_time as createTime, o.update_time as updateTime, case when o.attachments is null or o.attachments = '' or json_valid(o.attachments) = 0 then 0 else json_length(o.attachments) end as attachmentCount, coalesce(bc.bug_count, 0) as bugCount, coalesce(mc.message_count, 0) as messageCount, lt.user_name as lastMessageUser, lt.type as lastMessageType, lt.content as lastMessageContent, lt.create_time as lastMessageTime from jiedan_order o left join ( select order_id, count(*) as bug_count from jiedan_bug group by order_id ) bc on bc.order_id = o.id left join ( select order_id, count(*) as message_count, max(id) as last_id from jiedan_timeline where type in ('message', 'reply') group by order_id ) mc on mc.order_id = o.id left join jiedan_timeline lt on lt.id = mc.last_id
o.del_flag = 0 and o.owner_id = #{ownerId}
order by o.id desc

select version from jiedan_order
where id = #{id} and del_flag = 0
and owner_id = #{ownerId}

mapper.update:
update jiedan_order
order_no = #{orderNo}, title = #{title}, channel = #{channel}, customer = #{customer}, customer_account = #{customerAccount}, contact = #{contact}, amount = #{amount}, owner_id = #{ownerId}, status = #{status}, priority = #{priority}, deadline = #{deadline}, requirement = #{requirement}, attachments = #{attachments}, notes = #{notes}, note_attachments = #{noteAttachments}, unread = #{unread}, paid = #{paid}, received_amount = #{receivedAmount}, assign_state = #{assignState}, revisions = #{revisions}, update_time = #{updateTime}, version = version + 1
where id = #{id}
